---定时器回调
function DreamAdventuresMapSiteNode:TimerHandler()
    local index = self:GetIndex()
    local siteData = DreamAdventuresMgr:GetMapQuest()[index]
    if DreamAdventuresMgr:CheckSiteOpenTime(siteData.unlockCountdown) then return end
    
    local text = string.format(localize("距离开放：_num_", {_num_ =CfUtils.GetTimeHMS10(checkInt(siteData.unlockCountdown + DreamAdventuresMgr:GetEnterTimestamp() - os.time()))}))
    CfUtils.FillText(self.TextTitle, text)
end
--endregion handler

--region public
---初始化节点
function DreamAdventuresMapSiteNode:InitNode(index)
    self:SetIndex(index)
    local siteData = DreamAdventuresMgr:GetMapQuest()[index]
    if not siteData then return end

    local siteVo = CfUtils.GetCfVo(AutoIds.IdSetting6188, "DreamAdventuresMapVo", siteData.questId)
    if not siteVo then return end
    
    if not DreamAdventuresMgr:CheckSiteOpenTime(siteData.unlockCountdown) then
        -- 日期锁定
        CfUtils.SetUISwitchImage(self.ImgBgTitle, 2)
        CfUtils.SetActive(self.ImgLock, true)
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.ActivityDreamAdventureslStoryPlayerHeadNode, false)
        local text = string.format(localize("距离开放：_num_", {_num_ =CfUtils.GetTimeHMS10(checkInt(siteData.unlockCountdown + DreamAdventuresMgr:GetEnterTimestamp() - os.time()))}))
        CfUtils.FillText(self.TextTitle, text)
        self:StartTimer()
        return
    end

    -- 节点名称
    CfUtils.FillText(self.TextTitle, siteVo.name)
    
    -- 0未解锁 1已解锁 2已通关
    local status = checkInt(siteData.status)
    if status == 0 then
        CfUtils.SetUISwitchImage(self.ImgBgTitle, 2)
        CfUtils.SetActive(self.ImgLock, true)
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.ActivityDreamAdventureslStoryPlayerHeadNode, false)
    elseif status == 1 then
        CfUtils.SetUISwitchImage(self.ImgBgTitle, 1)
        CfUtils.SetActive(self.ImgLock, false)
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.ActivityDreamAdventureslStoryPlayerHeadNode, true)
    elseif status == 2 then
        CfUtils.SetUISwitchImage(self.ImgBgTitle, 1)
        CfUtils.SetActive(self.ImgLock, false)
        CfUtils.SetActive(self.ImgGet, true)
        CfUtils.SetActive(self.ActivityDreamAdventureslStoryPlayerHeadNode, false)
    end
end

---设置点击回调
---@param cb function 
function DreamAdventuresMapSiteNode:SetOnClickCallback(cb)
    self._cb = cb
end
--endregion public

--region private
function DreamAdventuresMapSiteNode:StartTimer()
    self:CloseTimer()
    TimerModule.Instance:AddTimer(self:GetTimerName(), 0, 1, Bind(self, self.TimerHandler))
end

function DreamAdventuresMapSiteNode:CloseTimer()
    TimerModule.Instance:RemoveTimer(self:GetTimerName())
end

function DreamAdventuresMapSiteNode:GetTimerName()
    return "DreamAdventuresMapSiteNode" .. self:GetIndex()
end
--endregion private

--region get / set
function DreamAdventuresMapSiteNode:SetIndex(index)
    self._index = checkInt(index)
end

function DreamAdventuresMapSiteNode:GetIndex()
    return self._index
end
